    ('admin.analytics.metrics.tail', 'zh-CN', '切分：产物由全球访客访问，用 UTC 才不会有跨时区的口径歧义。', 200, 'admin', 'admin/analytics.html', 1, now(), now()),
    ('admin.analytics.metrics.tail', 'en-US', ': artifacts are served to visitors worldwide, and UTC is the only way to avoid ambiguity across time zones.', 200, 'admin', 'admin/analytics.html', 1, now(), now()),
