    ('admin.masterdata.entities.hint', 'en-US', 'Click "View history" to lock onto that entity (the same as filling in entity type + entity id above).', 200, 'admin', 'admin/masterdata_changes.html', 1, now(), now()),
    ('admin.masterdata.filter.hint', 'zh-CN', '实体类型 + 实体 id 一起填即锁定单个实体，页面给出它的完整字段级时间线；时间区间是半开区间：since 含当天、until 含当天（内部转成次日零点）。', 200, 'admin', 'admin/masterdata_changes.html', 1, now(), now()),
    ('admin.masterdata.filter.hint', 'en-US', 'Filling in both entity type and entity id locks onto a single entity and shows its complete field-level timeline; the date range is half-open: since includes that day, until includes that day (converted to the next midnight internally).', 200, 'admin', 'admin/masterdata_changes.html', 1, now(), now()),
